  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Trazodone, a close structural analogue sharing a chlorophenyl and basic amine side chain, has human oral bioavailability of 63–91%, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Linezolid, which contains morpholine and amide functionality like the query, has ~100% absolute oral bioavailability in humans, supporting high oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Sematilide, a benzamide with a basic aminoethyl side chain closely matching the query scaffold, has absolute bioavailability of 46% from plasma, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Molsidomine, a morpholine-containing drug, has absolute bioavailability of 44 ± 15% in humans, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Imatinib has absolute oral bioavailability of 97.2% in healthy subjects, demonstrating that similar heteroaromatic/basic amine drugs can achieve near-complete oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Tazemetostat, despite lower absorption, has mean absolute bioavailability of 33.9%, still above the 20% threshold, supporting high classification.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a small benzamide with a morpholine-ethyl side chain. Multiple high-transfer analogues with the same scaffold or morpholine/amide features show absolute oral bioavailability well above 20%: trazodone 63–91%, linezolid ~100%, sematilide ~46%, molsidomine ~44%, and imatinib ~98%. Even the lowest measured analogue, tazemetostat at ~32–34%, exceeds the threshold. Therefore F ≥ 20% is strongly supported.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself is present.",
    "The modified-release formulation condition is not directly represented in the evidence, though the chemical class consistently exceeds the 20% threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

